Here is a complete, self-contained implementation of an LRU (Least Recently Used) cache in Rust.

It uses `std::collections::HashMap` for O(1) lookups and a custom **Doubly Linked List** (using `Rc` and `RefCell`) to manage the order of usage in O(1).

### The Implementation

```rust
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

// Type alias for a shared, mutable node
type NodeRef<K, V> = Rc<RefCell<Node<K, V>>>;

// The Node structure for the Doubly Linked List
struct Node<K, V> {
    key: K,
    value: V,
    prev: Option<NodeRef<K, V>>,
    next: Option<NodeRef<K, V>>,
}

impl<K, V> Node<K, V> {
    fn new(key: K, value: V) -> NodeRef<K, V> {
        Rc::new(RefCell::new(Node {
            key,
            value,
            prev: None,
            next: None,
        }))
    }
}

pub struct LRUCache<K, V> {
    capacity: usize,
    map: HashMap<K, NodeRef<K, V>>,
    // Head is the most recently used (MRU)
    head: Option<NodeRef<K, V>>,
    // Tail is the least recently used (LRU)
    tail: Option<NodeRef<K, V>>,
}

impl<K, V> LRUCache<K, V>
where
    K: Eq + std::hash::Hash + Clone,
    V: Clone,
{
    pub fn new(capacity: usize) -> Self {
        LRUCache {
            capacity,
            map: HashMap::with_capacity(capacity),
            head: None,
            tail: None,
        }
    }

    /// Retrieves a value and marks it as recently used. O(1)
    pub fn get(&mut self, key: &K) -> Option<V> {
        if let Some(node) = self.map.get(key).cloned() {
            // Move the node to the head (MRU position)
            self.move_to_head(node.clone());
            // Return a clone of the value
            Some(node.borrow().value.clone())
        } else {
            None
        }
    }

